?><!doctype html><html><head><meta charset="utf-8"><title><?= htmlspecialchars(appBrandTitle('Detailed Reports')) ?></title><link rel="stylesheet" href="css/style.css"><style>.report-page{max-width:1450px;margin:14px auto}.report-filter{background:#fff;padding:12px;border:1px solid #b9d8d5;border-radius:7px}.report-fields{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0}.report-fields label{user-select:none}.report-table{width:100%;border-collapse:collapse;background:#fff;font-size:.7rem}.report-table th{background:#0f766e;color:#fff}.report-table td,.report-table th{padding:7px;border-bottom:1px solid #d8e0e8;text-align:left;white-space:nowrap}.report-table tr:nth-child(even){background:#f2fbfa}</style></head><body><div class="app-shell"><aside class="app-sidebar"><?php renderAppBrand(); ?><nav class="sidebar-nav"><?php renderSidebarNav(); ?></nav><?php renderSidebarFooter(); ?></aside><div class="app-main"><?php renderAppHeader('Detailed Consignment Report', '📊'); ?><main class="app-body"><div class="report-page"><form class="report-filter" method="get"><div class="d-flex gap-2 flex-wrap"><input class="form-control" style="width:130px" type="date" name="from" value="<?=htmlspecialchars($filters['from']??'')?>"><input class="form-control" style="width:130px" type="date" name="to" value="<?=htmlspecialchars($filters['to']??'')?>"><input class="form-control" style="width:230px" name="search" value="<?=htmlspecialchars($filters['search']??'')?>" placeholder="Docket, party, consignee"><select class="form-select" style="width:170px" name="tracking"><option value="">All tracking status</option><?php foreach(['In Transit','Connecting to Next Destination','Out for Delivery','Delivered','Hold','Return'] as $v):?><option <?=$v===($filters['tracking']??'')?'selected':''?>><?=$v?></option><?php endforeach;?></select><select class="form-select" style="width:100px" name="priority"><option value="">Priority</option><option <?=$filters['priority']??''==='Normal'?'selected':''?>>Normal</option><option <?=$filters['priority']??''==='High'?'selected':''?>>High</option><option <?=$filters['priority']??''==='Urgent'?'selected':''?>>Urgent</option></select><select class="form-select" style="width:110px" name="pod"><option value="">All POD</option><option value="pending" <?=$filters['pod']??''==='pending'?'selected':''?>>Pending</option><option value="uploaded" <?=$filters['pod']??''==='uploaded'?'selected':''?>>Uploaded</option></select><button class="btn btn-primary btn-sm">Apply</button><button formaction="export_report.php" class="btn btn-success btn-sm">Download Excel</button></div><div class="report-fields"><label style="font-weight:700"><input type="checkbox" id="grpCommercial" data-fields="<?=htmlspecialchars(implode(',',$commercialFields))?>"> Commercial</label><?php foreach($columns as $key=>$label):?><label><input type="checkbox" class="field-check" name="fields[]" value="<?=$key?>" <?=in_array($key,$selected,true)?'checked':''?>> <?=$label?></label><?php endforeach;?></div></form><p><b><?=count($rows)?></b> matching dockets. Select fields above before downloading.</p><div style="overflow:auto"><table class="report-table"><tr><?php foreach($selected as $field):if(isset($columns[$field])):?><th><?=$columns[$field]?></th><?php endif;endforeach;?></tr><?php foreach($rows as $row):?><tr><?php foreach($selected as $field):if(isset($columns[$field])):?><td><?=htmlspecialchars((string)($row[$field]??''))?></td><?php endif;endforeach;?></tr><?php endforeach;?></table></div></div></main></div></div><script>(function(){const g=document.getElementById('grpCommercial');if(!g)return;const keys=(g.dataset.fields||'').split(',').map(s=>s.trim()).filter(Boolean);const getBoxes=()=>Array.from(document.querySelectorAll('input.field-check')).filter(cb=>keys.includes(cb.value));const sync=()=>{const boxes=getBoxes();g.checked=boxes.length>0&&boxes.every(b=>b.checked);};g.addEventListener('change',()=>{getBoxes().forEach(b=>{b.checked=g.checked;});});document.querySelectorAll('input.field-check').forEach(cb=>{if(keys.includes(cb.value))cb.addEventListener('change',sync);});sync();})();</script></body></html>
